arguments.command:
cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && cat > /tmp/list.sh <<'EOF'
for b in rachel monica phoebe joey chandler ross; do
  git log origin/friend/$b --format='%H%x09%ci%x09%B%x0a@@@' | awk -v br="friend/$b" '
    BEGIN{RS="@@@\n"; FS="\t"}
    {
      sha=$1; dt=$2; rest=$0;
      if (rest ~ /Friend-Message: 1/ && rest ~ /Episode: S06\/E04/) {
        # extract episode already known
        print sha "\t" dt "\t" br
      }
    }
  '
done
EOF
bash /tmp/list.sh | wc -l
